class Task:
    def __init__(self, id, e, s, p, d=None):
        self.id = id
        self.e = e  # execution_time
        self.s = s  # suspension_time
        self.p = p  # period
        self.d = d if d is not None else p # relative_deadline (implicit if not specified)
        self.u = self.e / self.p # utilization

def calculate_system_utilization(task_set):
    U_sum = 0
    for task in task_set:
        U_sum += task.u
    return U_sum

def calculate_job_tardiness(job_completion_time, job_absolute_deadline):
    return max(0, job_completion_time - job_absolute_deadline)

def check_basic_feasibility(task_set, m_processors):
    U_sum = calculate_system_utilization(task_set)
    if U_sum > m_processors:
        return False # Unbounded tardiness
    for task in task_set:
        if task.e + task.s > task.p or task.u > 1:
            return False # Task cannot meet its own requirements
    return True

class PSSchedule:
    def __init__(self, task_set):
        self.task_set = task_set

    def get_allocation(self, task_i, start_time, end_time):
        # In an ideal PS schedule, a task gets its utilization rate
        # multiplied by the duration it's active.
        # For simplicity, assuming task_i is active throughout [start_time, end_time)
        duration = end_time - start_time
        return duration * task_i.u

    def job_completion_time(self, job_i_j):
        # In PS, jobs complete exactly at their deadlines
        return job_i_j.absolute_deadline

def define_competing_jobs(all_jobs, job_l_j, t_d):
    d_set = set()
    for job_i_v in all_jobs:
        if job_i_v.absolute_deadline < t_d:
            d_set.add(job_i_v)
        elif job_i_v.absolute_deadline == t_d:
            if job_i_v.task_id <= job_l_j.task_id:
                d_set.add(job_i_v)
    return d_set

def get_task_allocation(task_i, t_start, t_end, schedule):
    total_allocation = 0
    for job_v in task_i.jobs:
        # Assuming schedule.get_job_allocation returns allocation for a specific job
        total_allocation += schedule.get_job_allocation(job_v, t_start, t_end)
    return total_allocation

def calculate_task_lag(task_i, current_time, actual_schedule, ps_schedule):
    total_task_lag = 0
    for job_v in task_i.jobs:
        total_task_lag += calculate_job_lag(job_v, current_time, actual_schedule, ps_schedule)
    return total_task_lag

class Task:
    # ... (previous attributes)
    def calculate_transformed_utilization(self):
        return (self.e + self.s) / self.p

class Task:
    # ... (previous attributes)
    def calculate_suspension_ratio(self):
        return self.s / self.p

def get_sorted_suspension_ratios(task_set):
    ratios = [task.calculate_suspension_ratio() for task in task_set]
    ratios.sort(reverse=True)
    return ratios

def get_jth_max_suspension_ratio(task_set, j):
    sorted_ratios = get_sorted_suspension_ratios(task_set)
    if 0 < j <= len(sorted_ratios):
        return sorted_ratios[j-1]
    return None

def find_latest_non_busy_interval_end(schedule, d_set, t_d):
    t_n = 0
    # Iterate backwards from t_d - 1 down to 0
    for t in range(t_d - 1, -1, -1):
        is_non_busy_for_d = False
        # Check if any processor is idle at t
        if schedule.is_any_processor_idle(t):
            # Check if any job in d_set is enabled and not executing (e.g., suspending) at t
            for job in d_set:
                if schedule.is_job_enabled_and_not_executing(job, t):
                    is_non_busy_for_d = True
                    break
        if is_non_busy_for_d:
            t_n = t + 1 # The end of the interval [t, t+1) is t+1
            break
    return t_n

def analyze_pessimism_root_cause(schedule, current_time, m_processors, d_set):
    if schedule.is_any_processor_idle(current_time):
        suspending_tardy_jobs_count = 0
        for job in d_set:
            if job.is_tardy() and job.is_enabled() and job.is_suspending_at(current_time):
                suspending_tardy_jobs_count += 1
        if suspending_tardy_jobs_count >= m_processors:
            # This is the identified worst-case scenario causing pessimism
            # LAG(d, current_time, S) is likely to increase
            return True
    return False

def verify_claim_2(transformed_schedule, m_processors, current_time):
    if transformed_schedule.is_any_processor_idle(current_time):
        enabled_tardy_jobs_count = 0
        for task in transformed_schedule.active_tasks:
            if task.has_enabled_tardy_job_with_deadline_at_or_before(current_time):
                enabled_tardy_jobs_count += 1
        # If this condition is met, Claim 2 holds
        return enabled_tardy_jobs_count <= (m_processors - 1)
    return True # If busy, Claim 2 is trivially true for this instant

def check_ps_schedule_validity(task_set, m_processors):
    U_sum = calculate_system_utilization(task_set)
    sorted_suspension_ratios = get_sorted_suspension_ratios(task_set)
    # Sum of the m largest suspension ratios
    sum_m_largest_v = sum(sorted_suspension_ratios[:m_processors])

    if U_sum + sum_m_largest_v <= m_processors:
        return True
    else:
        return False
